SELECT windowclientwidth, windowclientheight, count(*) FROM (SELECT * FROM streamed_table('/pgch_2225445_1_1_0', 'eventdate Date, counterid Int32, isrefresh Int16, windowclientwidth Int16, windowclientheight Int16, dontcounthits Int16, urlhash Int64')) WHERE ((eventdate >= '2013-07-01')) AND ((eventdate <= '2013-07-31')) AND ((counterid = 62)) AND ((isrefresh = 0)) AND ((dontcounthits = 0)) AND ((urlhash = 2868770270353813622)) GROUP BY windowclientwidth, windowclientheight ORDER BY count(*) DESC NULLS FIRST LIMIT 10 OFFSET 10000
